export function CmsHomeHighlights({language='en'}:{language?:'en'|'ar'}){
  const [banners,setBanners]=useState<Array<{id:string;title:string;title_ar:string|null;image_path:string|null;target_url:string|null}>>([]);const [featured,setFeatured]=useState<Array<{id:string;title:string;description:string|null;target_url:string|null;content_type:string}>>([]);const [loading,setLoading]=useState(Boolean(supabase));const [error,setError]=useState('');
  useEffect(()=>{if(!supabase){setLoading(false);return;}let alive=true;void Promise.all([supabase.from('banners').select('id,title,title_ar,image_path,target_url').eq('is_active',true).eq('placement','home').order('sort_order').limit(5),supabase.from('featured_content').select('id,title,description,target_url,content_type').eq('is_active',true).eq('placement','home').order('sort_order').limit(6)]).then(([b,f])=>{if(!alive)return;if(b.error||f.error)setError(b.error?.message??f.error?.message??'Homepage content could not be loaded.');setBanners((b.data??[]) as typeof banners);setFeatured((f.data??[]) as typeof featured);setLoading(false);});return()=>{alive=false;};},[]);
  if(!supabase)return null;
  if(loading)return <section className="content"><div className="empty-note">{uiText('Loading featured content…')}</div></section>;
  if(error)return <section className="content"><div className="empty-note" role="alert">{error}</div></section>;
  if(!banners.length&&!featured.length)return null;
  return <>{banners.length>0&&<section className="content" style={{paddingTop:8}}><div className="office-strip">{banners.map(row=><a className="office-card" key={row.id} href={row.target_url??'/cars'} style={{backgroundImage:row.image_path?`linear-gradient(90deg,rgba(20,38,28,.78),rgba(20,38,28,.1)),url("${row.image_path}")`:undefined,backgroundSize:'cover',color:row.image_path?'white':undefined}}><span><h3>{language==='ar'&&row.title_ar?row.title_ar:row.title}</h3>{row.target_url&&<small>{uiText("Explore")} <ChevronRight size={12}/></small>}</span></a>)}</div></section>}{featured.length>0&&<section className="content"><div className="section-head"><div><span className="eyebrow">{uiText('FEATURED')}</span><h2>{uiText('Discover more with Rentora')}</h2></div></div><div className="office-strip">{featured.map(row=><a className="office-card" key={row.id} href={row.target_url??'/cars'}><span><small>{row.content_type}</small><h3>{row.title}</h3><p>{row.description}</p></span></a>)}</div></section>}</>;
}

type ReviewRow={id:string;booking_id:string;rating:number;title:string|null;body:string|null;status:string;moderation_note:string|null;created_at:string;profiles?:{full_name:string}|null;rental_offices?:{name:string}|null;vehicles?:{make:string;model:string}|null};
export function ReviewsManagement({admin,officeId,notify}:{admin:boolean;officeId:string;notify:(message:string)=>void}){
  const [rows,setRows]=useState<ReviewRow[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [query,setQuery]=useState('');const [filter,setFilter]=useState('all');const [page,setPage]=useState(0);const [notes,setNotes]=useState<Record<string,string>>({});
  const load=useCallback(async()=>{if(!supabase)return;setLoading(true);setError('');let officeUuid='';if(!admin){const office=await supabase.from('rental_offices').select('id').eq('slug',officeId).maybeSingle();if(office.error||!office.data){setError(office.error?.message??'Office not found.');setLoading(false);return;}officeUuid=office.data.id;}let q=supabase.from('reviews').select('id,booking_id,rating,title,body,status,moderation_note,created_at,profiles:profiles!reviews_customer_id_fkey(full_name),rental_offices(name),vehicles(make,model)').order('created_at',{ascending:false}).limit(500);if(!admin)q=q.eq('office_id',officeUuid);const result=await q;if(result.error)setError(result.error.message);setRows((result.data??[]) as unknown as ReviewRow[]);setLoading(false);},[admin,officeId]);
  useEffect(()=>{void load();},[load]);if(!supabase)return <BackendPrompt/>;const filtered=rows.filter(row=>(filter==='all'||row.status===filter)&&`${row.title??''} ${row.body??''} ${row.profiles?.full_name??''} ${row.status}`.toLowerCase().includes(query.toLowerCase()));const size=20;const visible=filtered.slice(page*size,(page+1)*size);
  const moderate=async(row:ReviewRow,status:string)=>{if(!supabase)return;const result=await supabase.from('reviews').update({status,moderation_note:notes[row.id]?.trim()||null,moderated_by:(await supabase.auth.getUser()).data.user?.id??null}).eq('id',row.id);if(result.error)setError(result.error.message);else{notify(uiText('Review moderation saved.'));await load();}};
  return <div className="panel-card"><div className="panel-head"><div><h3>{admin?'Review moderation':'Customer reviews'}</h3><p>{uiText('Review visibility and moderation notes are stored in Supabase.')}</p></div><button className="quiet-button" onClick={()=>void load()}><RefreshCw size={13}/> {uiText('Refresh')}</button></div>{error&&<div className="empty-note" role="alert">{error}</div>}<div className="toolbar" style={{marginBottom:12}}><input className="search-input" value={query} onChange={event=>{setQuery(event.target.value);setPage(0);}} placeholder={uiText('Search review or customer')}/><select value={filter} onChange={event=>{setFilter(event.target.value);setPage(0);}}><option value="all">{uiText('All statuses')}</option>{['pending','published','hidden','reported','removed'].map(value=><option key={value}>{value}</option>)}</select></div><div className="table-wrap"><table className="data-table"><thead><tr><th>{uiText('Review')}</th><th>{uiText('Customer')}</th><th>{uiText('Office / vehicle')}</th><th>{uiText('Rating')}</th><th>{uiText('Status')}</th><th>{uiText('Moderation')}</th><th>{uiText('Action')}</th></tr></thead><tbody>{visible.map(row=><tr key={row.id}><td><strong>{row.title??'Untitled review'}</strong><small style={{display:'block'}}>{row.body??''}</small></td><td>{row.profiles?.full_name??'Customer'}</td><td>{row.rental_offices?.name??'Office'}{row.vehicles&&<small style={{display:'block'}}>{row.vehicles.make} {row.vehicles.model}</small>}</td><td>{row.rating} / 5</td><td>{row.status}</td><td><input aria-label={uiText('Moderation note')} maxLength={1000} value={notes[row.id]??row.moderation_note??''} onChange={event=>setNotes({...notes,[row.id]:event.target.value})}/></td><td>{(admin||row.status!=='published')&&<select value={row.status} onChange={event=>void moderate(row,event.target.value)}>{['pending','published','hidden','reported','removed'].map(value=><option key={value}>{value}</option>)}</select>}</td></tr>)}</tbody></table>{loading&&<div className="empty-note">{uiText('Loading reviews…')}</div>}{!loading&&!visible.length&&<div className="empty-note">{uiText('No reviews match this search.')}</div>}</div>{filtered.length>size&&<div className="toolbar" style={{justifyContent:'flex-end',marginTop:10}}><button className="quiet-button" disabled={!page} onClick={()=>setPage(p=>p-1)}>{uiText('Previous')}</button><span>{uiText("Page")} {page+1} {uiText("of")} {Math.ceil(filtered.length/size)}</span><button className="quiet-button" disabled={(page+1)*size>=filtered.length} onClick={()=>setPage(p=>p+1)}>{uiText('Next')}</button></div>}</div>;
}

type PromoRow={id:string;office_id:string|null;coupon_id:string|null;title:string;description:string|null;starts_at:string;ends_at:string;usage_limit:number|null;is_active:boolean};
export function PromotionsManagement({admin,officeId,notify}:{admin:boolean;officeId:string;notify:(message:string)=>void}){
  const [rows,setRows]=useState<PromoRow[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [query,setQuery]=useState('');const [page,setPage]=useState(0);const [show,setShow]=useState(false);const [editing,setEditing]=useState<PromoRow|null>(null);const [form,setForm]=useState({title:'',description:'',starts_at:'',ends_at:'',usage_limit:'',is_active:true});const [officeUuid,setOfficeUuid]=useState('');
  const load=useCallback(async()=>{if(!supabase)return;setLoading(true);setError('');let uuid='';if(!admin){const office=await supabase.from('rental_offices').select('id').eq('slug',officeId).maybeSingle();if(office.error||!office.data){setError(office.error?.message??'Office not found.');setLoading(false);return;}uuid=office.data.id;setOfficeUuid(uuid);}let q=supabase.from('promotions').select('id,office_id,coupon_id,title,description,starts_at,ends_at,usage_limit,is_active').order('starts_at',{ascending:false}).limit(500);if(!admin)q=q.eq('office_id',uuid);const result=await q;if(result.error)setError(result.error.message);setRows((result.data??[]) as PromoRow[]);setLoading(false);},[admin,officeId]);
  useEffect(()=>{void load();},[load]);if(!supabase)return <BackendPrompt/>;const filtered=rows.filter(row=>`${row.title} ${row.description??''}`.toLowerCase().includes(query.toLowerCase()));const size=20;const visible=filtered.slice(page*size,(page+1)*size);
  const open=(row?:PromoRow)=>{setEditing(row??null);setForm(row?{title:row.title,description:row.description??'',starts_at:row.starts_at.slice(0,16),ends_at:row.ends_at.slice(0,16),usage_limit:row.usage_limit==null?'':String(row.usage_limit),is_active:row.is_active}:{title:'',description:'',starts_at:new Date().toISOString().slice(0,16),ends_at:'',usage_limit:'',is_active:true});setShow(true);};
  const save=async(event:FormEvent)=>{event.preventDefault();if(!supabase)return;const start=new Date(form.starts_at);const end=new Date(form.ends_at);const usage=form.usage_limit?Number(form.usage_limit):null;if(form.title.trim().length<3||!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||end<=start||(usage!==null&&(!Number.isInteger(usage)||usage<1))){setError('Enter a title, valid end date after start, and positive usage limit.');return;}const values={office_id:admin?editing?.office_id??null:officeUuid,title:form.title.trim(),description:form.description.trim()||null,starts_at:start.toISOString(),ends_at:end.toISOString(),usage_limit:usage,is_active:form.is_active};const result=editing?await supabase.from('promotions').update(values).eq('id',editing.id):await supabase.from('promotions').insert(values);if(result.error)setError(result.error.message);else{setShow(false);notify(uiText('Promotion saved.'));await load();}};
  const remove=async(row:PromoRow)=>{if(!supabase||!window.confirm(`Delete promotion “${row.title}”?`))return;const result=await supabase.from('promotions').delete().eq('id',row.id);if(result.error)setError(result.error.message);else{notify(uiText('Promotion deleted.'));await load();}};
  return <div className="panel-card"><div className="panel-head"><div><h3>{uiText('Promotions')}</h3><p>{uiText('Manage active periods and usage limits. Coupon discounts are separately validated by the booking RPC.')}</p></div><div className="toolbar"><button className="quiet-button" onClick={()=>void load()}><RefreshCw size={13}/> {uiText('Refresh')}</button><button className="btn btn-sm" onClick={()=>open()}><Plus size={13}/> {uiText('Add promotion')}</button></div></div>{error&&<div className="empty-note" role="alert">{error}</div>}<div className="toolbar" style={{marginBottom:12}}><input className="search-input" value={query} onChange={event=>{setQuery(event.target.value);setPage(0);}} placeholder={uiText('Search promotions')}/></div><div className="table-wrap"><table className="data-table"><thead><tr><th>{uiText('Title')}</th><th>{uiText('Description')}</th><th>{uiText('Starts')}</th><th>{uiText('Ends')}</th><th>{uiText('Usage cap')}</th><th>{uiText('Status')}</th><th>{uiText('Actions')}</th></tr></thead><tbody>{visible.map(row=><tr key={row.id}><td>{row.title}</td><td>{row.description??'—'}</td><td>{new Date(row.starts_at).toLocaleString()}</td><td>{new Date(row.ends_at).toLocaleString()}</td><td>{row.usage_limit??'Unlimited'}</td><td>{row.is_active?'Active':'Inactive'}</td><td><button className="quiet-button" onClick={()=>open(row)}>{uiText('Edit')}</button><button className="quiet-button" onClick={()=>void remove(row)}><Trash2 size={13}/></button></td></tr>)}</tbody></table>{loading&&<div className="empty-note">{uiText('Loading promotions…')}</div>}{!loading&&!visible.length&&<div className="empty-note">{uiText('No promotions match this search.')}</div>}</div>{filtered.length>size&&<div className="toolbar" style={{justifyContent:'flex-end',marginTop:10}}><button className="quiet-button" disabled={!page} onClick={()=>setPage(p=>p-1)}>{uiText('Previous')}</button><span>{uiText("Page")} {page+1} {uiText("of")} {Math.ceil(filtered.length/size)}</span><button className="quiet-button" disabled={(page+1)*size>=filtered.length} onClick={()=>setPage(p=>p+1)}>{uiText('Next')}</button></div>}
  {show&&<div className="modal-backdrop" onClick={()=>setShow(false)}><form className="modal" onSubmit={save} onClick={event=>event.stopPropagation()}><div className="modal-head"><div><h2>{editing?'Edit':'Add'} {uiText("promotion")}</h2><p>{uiText('Validate schedule and usage before publishing.')}</p></div><button type="button" className="modal-close" onClick={()=>setShow(false)}>×</button></div><div className="form-grid"><label className="field full">{uiText("Title")}<input required minLength={3} maxLength={160} value={form.title} onChange={event=>setForm({...form,title:event.target.value})}/></label><label className="field full">{uiText("Description")}<textarea maxLength={1000} value={form.description} onChange={event=>setForm({...form,description:event.target.value})}/></label><label className="field">{uiText("Starts")}<input type="datetime-local" required value={form.starts_at} onChange={event=>setForm({...form,starts_at:event.target.value})}/></label><label className="field">{uiText("Ends")}<input type="datetime-local" required value={form.ends_at} onChange={event=>setForm({...form,ends_at:event.target.value})}/></label><label className="field">{uiText("Usage cap")}<input type="number" min="1" value={form.usage_limit} onChange={event=>setForm({...form,usage_limit:event.target.value})} placeholder={uiText('Unlimited')}/></label><label className="field">{uiText("State")}<select value={String(form.is_active)} onChange={event=>setForm({...form,is_active:event.target.value==='true'})}><option value="true">{uiText('Active')}</option><option value="false">{uiText('Inactive')}</option></select></label></div><button className="btn btn-block">{uiText('Save promotion')}</button></form></div>}</div>;
}

type CustomerRow={user_id:string;full_name:string;email:string|null;phone:string|null;is_blacklisted:boolean;blacklist_reason:string|null;created_at:string;profiles?:{full_name:string;email:string|null}|null};
export function CustomerDirectory({officeId,notify}:{officeId?:string;notify:(message:string)=>void}){
  const [rows,setRows]=useState<CustomerRow[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [query,setQuery]=useState('');const [page,setPage]=useState(0);const [officeUuid,setOfficeUuid]=useState('');
  const load=useCallback(async()=>{if(!supabase)return;setLoading(true);setError('');let uuid='';if(officeId){const office=await supabase.from('rental_offices').select('id').eq('slug',officeId).maybeSingle();if(office.error||!office.data){setError(office.error?.message??'Office not found.');setLoading(false);return;}uuid=office.data.id;setOfficeUuid(uuid);}let q=supabase.from('customers').select('user_id,full_name,email,phone,is_blacklisted,blacklist_reason,created_at,profiles(full_name,email)').order('created_at',{ascending:false}).limit(500);if(uuid){const bookingIds=await supabase.from('bookings').select('customer_id').eq('office_id',uuid).limit(1000);if(bookingIds.error){setError(bookingIds.error.message);setLoading(false);return;}const ids=[...new Set((bookingIds.data??[]).map(row=>row.customer_id))];if(!ids.length){setRows([]);setLoading(false);return;}q=q.in('user_id',ids);}const result=await q;if(result.error)setError(result.error.message);setRows((result.data??[]) as unknown as CustomerRow[]);setLoading(false);},[officeId]);
  useEffect(()=>{void load();},[load]);if(!supabase)return <BackendPrompt/>;const filtered=rows.filter(row=>`${row.full_name} ${row.email??''} ${row.phone??''} ${row.is_blacklisted?'blacklisted':''}`.toLowerCase().includes(query.toLowerCase()));const size=20;const visible=filtered.slice(page*size,(page+1)*size);
  const blacklist=async(row:CustomerRow)=>{if(!supabase)return;const reason=row.is_blacklisted?null:prompt('Reason for restricting this customer?');if(!row.is_blacklisted&&!reason?.trim())return;const result=await supabase.from('customers').update({is_blacklisted:!row.is_blacklisted,blacklist_reason:row.is_blacklisted?null:reason?.trim()}).eq('user_id',row.user_id);if(result.error)setError(result.error.message);else{notify(row.is_blacklisted?'Customer restriction removed.':'Customer restricted.');await load();}};
  return <div className="panel-card"><div className="panel-head"><div><h3>{uiText('Customers')}</h3><p>{officeUuid?'Customers with bookings at this office.':'Platform customer directory.'}</p></div><button className="quiet-button" onClick={()=>void load()}><RefreshCw size={13}/> {uiText('Refresh')}</button></div>{error&&<div className="empty-note" role="alert">{error}</div>}<div className="toolbar" style={{marginBottom:12}}><input className="search-input" value={query} onChange={event=>{setQuery(event.target.value);setPage(0);}} placeholder={uiText('Search customer name, email, or phone')}/></div><div className="table-wrap"><table className="data-table"><thead><tr><th>{uiText('Customer')}</th><th>{uiText('Email')}</th><th>{uiText('Phone')}</th><th>{uiText('Since')}</th><th>{uiText('Status')}</th>{!officeId&&<th>{uiText('Action')}</th>}</tr></thead><tbody>{visible.map(row=><tr key={row.user_id}><td>{row.full_name||row.profiles?.full_name||'Customer'}</td><td>{row.email??row.profiles?.email??'—'}</td><td>{row.phone??'—'}</td><td>{new Date(row.created_at).toLocaleDateString()}</td><td>{row.is_blacklisted?'Restricted':'Active'}{row.blacklist_reason&&<small style={{display:'block'}}>{row.blacklist_reason}</small>}</td>{!officeId&&<td><button className="quiet-button" onClick={()=>void blacklist(row)}>{row.is_blacklisted?'Restore':'Restrict'}</button></td>}</tr>)}</tbody></table>{loading&&<div className="empty-note">{uiText('Loading customers…')}</div>}{!loading&&!visible.length&&<div className="empty-note">{uiText('No customers match this search.')}</div>}</div>{filtered.length>size&&<div className="toolbar" style={{justifyContent:'flex-end',marginTop:10}}><button className="quiet-button" disabled={!page} onClick={()=>setPage(p=>p-1)}>{uiText('Previous')}</button><span>{uiText("Page")} {page+1} {uiText("of")} {Math.ceil(filtered.length/size)}</span><button className="quiet-button" disabled={(page+1)*size>=filtered.length} onClick={()=>setPage(p=>p+1)}>{uiText('Next')}</button></div>}</div>;
}

type NotificationRow={id:string;recipient_id:string|null;audience:string|null;office_id:string|null;title:string;body:string;channel:string;read_at:string|null;scheduled_at:string|null;sent_at:string|null;created_at:string};
export function NotificationsManagement({notify}:{notify:(message:string)=>void}){
  const [rows,setRows]=useState<NotificationRow[]>([]);const [loading,setLoading]=useState(false);const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [query,setQuery]=useState('');const [page,setPage]=useState(0);const [show,setShow]=useState(false);const [form,setForm]=useState({title:'',body:'',audience:'all'});
  const load=useCallback(async()=>{if(!supabase)return;setLoading(true);setError('');const result=await supabase.from('notifications').select('id,recipient_id,audience,office_id,title,body,channel,read_at,scheduled_at,sent_at,created_at').order('created_at',{ascending:false}).limit(500);if(result.error)setError(result.error.message);setRows((result.data??[]) as NotificationRow[]);setLoading(false);},[]);useEffect(()=>{void load();},[load]);if(!supabase)return <BackendPrompt/>;
  const filtered=rows.filter(row=>`${row.title} ${row.body} ${row.audience??''} ${row.channel}`.toLowerCase().includes(query.toLowerCase()));const size=20;const visible=filtered.slice(page*size,(page+1)*size);
  const create=async(event:FormEvent)=>{event.preventDefault();if(!supabase)return;if(form.title.trim().length<3||form.title.trim().length>160||form.body.trim().length<3||form.body.trim().length>4000){setError('Title must contain 3–160 characters and message 3–4,000 characters.');return;}setSaving(true);setError('');const result=await supabase.rpc('broadcast_in_app_notification',{p_title:form.title.trim(),p_body:form.body.trim(),p_audience:form.audience});setSaving(false);if(result.error)setError(result.error.message);else{setShow(false);setForm({title:'',body:'',audience:'all'});notify(`Notice delivered to ${result.data??0} accounts.`);await load();}};
  const remove=async(row:NotificationRow)=>{if(!supabase||!window.confirm(`Delete notification “${row.title}”?`))return;const result=await supabase.from('notifications').delete().eq('id',row.id);if(result.error)setError(result.error.message);else{notify(uiText('Notification deleted.'));await load();}};
  return <div className="panel-card"><div className="panel-head"><div><h3>{uiText('In-app notifications')}</h3><p>{uiText('Broadcasts create one inbox notification per recipient and an audit record.')}</p></div><div className="toolbar"><button className="quiet-button" onClick={()=>void load()}><RefreshCw size={13}/> {uiText('Refresh')}</button><button className="btn btn-sm" onClick={()=>setShow(true)}><Plus size={13}/> {uiText('Create notice')}</button></div></div>{error&&<div className="empty-note" role="alert">{error}</div>}<div className="toolbar" style={{marginBottom:12}}><input className="search-input" value={query} onChange={event=>{setQuery(event.target.value);setPage(0);}} placeholder={uiText('Search notices')}/></div><div className="table-wrap"><table className="data-table"><thead><tr><th>{uiText('Title')}</th><th>{uiText('Message')}</th><th>{uiText('Audience')}</th><th>{uiText('Channel')}</th><th>{uiText('Published')}</th><th>{uiText('Actions')}</th></tr></thead><tbody>{visible.map(row=><tr key={row.id}><td>{row.title}</td><td>{row.body}</td><td>{row.recipient_id??row.audience??'—'}</td><td>{row.channel}</td><td>{row.sent_at?new Date(row.sent_at).toLocaleString():'—'}</td><td><button className="quiet-button" onClick={()=>void remove(row)}><Trash2 size={13}/></button></td></tr>)}</tbody></table>{loading&&<div className="empty-note">{uiText('Loading notices…')}</div>}{!loading&&!visible.length&&<div className="empty-note">{uiText('No notifications match this search.')}</div>}</div>{filtered.length>size&&<div className="toolbar" style={{justifyContent:'flex-end',marginTop:10}}><button className="quiet-button" disabled={!page} onClick={()=>setPage(p=>p-1)}>{uiText('Previous')}</button><span>{uiText("Page")} {page+1} {uiText("of")} {Math.ceil(filtered.length/size)}</span><button className="quiet-button" disabled={(page+1)*size>=filtered.length} onClick={()=>setPage(p=>p+1)}>{uiText('Next')}</button></div>}{show&&<div className="modal-backdrop" onClick={()=>!saving&&setShow(false)}><form className="modal" onSubmit={create} onClick={event=>event.stopPropagation()}><div className="modal-head"><div><h2>{uiText('Create in-app notice')}</h2><p>{uiText('Recipients receive a saved inbox item immediately.')}</p></div><button type="button" className="modal-close" disabled={saving} onClick={()=>setShow(false)}>×</button></div><div className="form-grid"><label className="field full">{uiText("Title")}<input required minLength={3} maxLength={160} value={form.title} onChange={event=>setForm({...form,title:event.target.value})}/></label><label className="field full">{uiText("Message")}<textarea required minLength={3} maxLength={4000} value={form.body} onChange={event=>setForm({...form,body:event.target.value})}/></label><label className="field">{uiText("Audience")}<select value={form.audience} onChange={event=>setForm({...form,audience:event.target.value})}><option value="all">{uiText('All accounts')}</option><option value="customer">{uiText('Customers')}</option><option value="office">{uiText('Office owners and staff')}</option><option value="platform">{uiText('Platform staff')}</option></select></label></div>{error&&<div className="empty-note" role="alert">{error}</div>}<button className="btn btn-block" disabled={saving}>{saving?'Sending…':'Send notice'}</button></form></div>}</div>;
}

type OfficeProfileRow={id:string;name:string;slug:string;description:string|null;address:string;phone:string|null;email:string|null;cancellation_policy:Record<string,unknown>;delivery_options:unknown[];working_hours:Record<string,unknown>};
export function OfficeProfileManagement({officeId,notify}:{officeId:string;notify:(message:string)=>void}){
  const [office,setOffice]=useState<OfficeProfileRow|null>(null);const [loading,setLoading]=useState(false);const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [form,setForm]=useState({name:'',description:'',address:'',phone:'',email:'',workingHours:'{}',cancellationPolicy:'{}',deliveryOptions:'[]'});
  const load=useCallback(async()=>{if(!supabase)return;setLoading(true);setError('');const result=await supabase.from('rental_offices').select('id,name,slug,description,address,phone,email,cancellation_policy,delivery_options,working_hours').eq('slug',officeId).maybeSingle();if(result.error||!result.data){setError(result.error?.message??'Office profile not found.');setLoading(false);return;}const row=result.data as OfficeProfileRow;setOffice(row);setForm({name:row.name,description:row.description??'',address:row.address,phone:row.phone??'',email:row.email??'',workingHours:JSON.stringify(row.working_hours,null,2),cancellationPolicy:JSON.stringify(row.cancellation_policy,null,2),deliveryOptions:JSON.stringify(row.delivery_options,null,2)});setLoading(false);},[officeId]);
  useEffect(()=>{void load();},[load]);if(!supabase)return <BackendPrompt/>;
  const save=async(event:FormEvent)=>{event.preventDefault();if(!supabase||!office)return;let workingHours:Record<string,unknown>;let cancellationPolicy:Record<string,unknown>;let deliveryOptions:unknown[];try{workingHours=JSON.parse(form.workingHours) as Record<string,unknown>;cancellationPolicy=JSON.parse(form.cancellationPolicy) as Record<string,unknown>;deliveryOptions=JSON.parse(form.deliveryOptions) as unknown[];if(Array.isArray(workingHours)||Array.isArray(cancellationPolicy)||!Array.isArray(deliveryOptions))throw new Error();}catch{setError('Hours and policy fields must be JSON objects; delivery options must be an array.');return;}if(form.name.trim().length<2||form.address.trim().length<3||(form.email&&!/^\S+@\S+\.\S+$/.test(form.email))){setError('Enter an office name, address, and valid contact email.');return;}setSaving(true);const result=await supabase.from('rental_offices').update({name:form.name.trim(),description:form.description.trim()||null,address:form.address.trim(),phone:form.phone.trim()||null,email:form.email.trim()||null,working_hours:workingHours,cancellation_policy:cancellationPolicy,delivery_options:deliveryOptions}).eq('id',office.id);setSaving(false);if(result.error)setError(result.error.message);else{notify(uiText('Office profile saved.'));await load();}};
  return <div className="panel-card"><div className="panel-head"><div><h3>{uiText('Office profile and settings')}</h3><p>{uiText('Profile edits are restricted by office ownership and audited in the database.')}</p></div><button className="quiet-button" onClick={()=>void load()}><RefreshCw size={13}/> {uiText('Refresh')}</button></div>{error&&<div className="empty-note" role="alert">{error}</div>}{loading&&<div className="empty-note">{uiText('Loading office profile…')}</div>}{office&&<form onSubmit={save}><div className="form-grid"><label className="field">{uiText("Office name")}<input required minLength={2} maxLength={160} value={form.name} onChange={event=>setForm({...form,name:event.target.value})}/></label><label className="field">{uiText("Public slug")}<input value={office.slug} readOnly/></label><label className="field">{uiText("Contact email")}<input type="email" value={form.email} onChange={event=>setForm({...form,email:event.target.value})}/></label><label className="field">{uiText("Phone")}<input maxLength={40} value={form.phone} onChange={event=>setForm({...form,phone:event.target.value})}/></label><label className="field full">{uiText("Street address")}<input required minLength={3} maxLength={500} value={form.address} onChange={event=>setForm({...form,address:event.target.value})}/></label><label className="field full">{uiText("Description")}<textarea maxLength={2000} rows={4} value={form.description} onChange={event=>setForm({...form,description:event.target.value})}/></label><label className="field">{uiText("Working hours (JSON)")}<textarea rows={5} value={form.workingHours} onChange={event=>setForm({...form,workingHours:event.target.value})}/></label><label className="field">{uiText("Cancellation policy (JSON)")}<textarea rows={5} value={form.cancellationPolicy} onChange={event=>setForm({...form,cancellationPolicy:event.target.value})}/></label><label className="field full">{uiText("Delivery options (JSON array)")}<textarea rows={3} value={form.deliveryOptions} onChange={event=>setForm({...form,deliveryOptions:event.target.value})}/></label></div><button className="btn" disabled={saving}>{saving?'Saving…':'Save office profile'}</button></form>}</div>;
}
